solutionCode:
class SpeedOutOfRangeException(message: String) : Exception(message)

fun setSafeSpeed(speed: Double): Double {
    if (speed < -1.0 || speed > 1.0) {
        throw SpeedOutOfRangeException("Invalid speed: $speed")
    }
    return speed
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testValidSpeed() {
        Assert.assertEquals(0.8, setSafeSpeed(0.8), 0.001)
    }

    @Test
    fun testZeroSpeed() {
        Assert.assertEquals(0.0, setSafeSpeed(0.0), 0.001)
    }

    @Test
    fun testBoundaryMax() {
        Assert.assertEquals(1.0, setSafeSpeed(1.0), 0.001)
    }

    @Test
    fun testBoundaryMin() {
        Assert.assertEquals(-1.0, setSafeSpeed(-1.0), 0.001)
    }

    @Test
    fun testSpeedTooHighMessage() {
        try {
            setSafeSpeed(3.0)
            Assert.fail("Should have thrown SpeedOutOfRangeException")
        } catch (e: SpeedOutOfRangeException) {
            Assert.assertEquals("Invalid speed: 3.0", e.message)
        }
    }

    @Test(expected = SpeedOutOfRangeException::class)
    fun testSpeedTooLow() {
        setSafeSpeed(-1.5)
    }

    @Test
    fun testExceptionExtendsException() {
        val exception = SpeedOutOfRangeException("test")
        Assert.assertTrue(exception is Exception)
    }
}
